import path from "path"
import { FilePath } from "./path"
import { globby } from "globby"

export function toPosixPath(fp: string): string {
  return fp.split(path.sep).join("/")
}

export async function glob(
  pattern: string,
  cwd: string,
  ignorePatterns: string[],
): Promise<FilePath[]> {
  const fps = (
    await globby(pattern, {
      cwd,
      ignore: ignorePatterns,
      // content/ is generated by scripts/org-to-md.mjs and listed in .gitignore,
      // but the build still has to read it, so do not follow .gitignore here.
      // Ignore rules come from ignorePatterns in quartz.config.yaml.
      gitignore: false,
    })
  ).map(toPosixPath)
  return fps as FilePath[]
}
